tests.code:
int arr[] = {4, 8, 2};
Stats s{arr};
static_assert(std::is_same_v<decltype(s), Stats<int>>, "deduce element type");
CHECK_EQ(s.min, 2);
CHECK_EQ(s.max, 8);

Stats p{1, 2};
static_assert(std::is_same_v<decltype(p), Stats<int>>, "pair still deduces");
CHECK_EQ(p.min, 1);
CHECK_EQ(p.max, 2);
